<?php
namespace App\Policies\Tenant\Reservations;
use App\Models\Tenant\Branch; use App\Models\Tenant\Reservation; use App\Models\Tenant\User; use App\Services\Tenant\Access\TenantUserAccessService;
class ReservationPolicy { public function __construct(private readonly TenantUserAccessService $access){} public function viewAny(User $u, Branch $b):bool{return $this->access->canManage($u,'reservations.view',$b);} public function create(User $u, Branch $b):bool{return $this->access->canManage($u,'reservations.create',$b);} public function view(User $u,Reservation $r,Branch $b):bool{return $r->branch_id===$b->id && $this->viewAny($u,$b);} public function update(User $u,Reservation $r,Branch $b):bool{return $this->view($u,$r,$b)&&$this->access->canManage($u,'reservations.update',$b);} public function seat(User $u,Reservation $r,Branch $b):bool{return $this->view($u,$r,$b)&&$this->access->canManage($u,'reservations.seat',$b);} public function complete(User $u,Reservation $r,Branch $b):bool{return $this->view($u,$r,$b)&&$this->access->canManage($u,'reservations.complete',$b);} public function cancel(User $u,Reservation $r,Branch $b):bool{return $this->view($u,$r,$b)&&$this->access->canManage($u,'reservations.cancel',$b);} public function noShow(User $u,Reservation $r,Branch $b):bool{return $this->view($u,$r,$b)&&$this->access->canManage($u,'reservations.no_show',$b);} }
